def solid_lines(grid):
    """Indices of full rows and full columns that are one nonzero color throughout: ('r', i) / ('c', j)."""
    h, w = len(grid), len(grid[0])
    out = [('r', i) for i in range(h) if len(set(grid[i])) == 1 and grid[i][0] != 0]
    out += [('c', j) for j in range(w) if len({row[j] for row in grid}) == 1 and grid[0][j] != 0]
    return out

def overlap_half(grid, color=2):
    """Split the grid at the solid separator line that leaves two equal halves; cells nonzero in both halves become color."""
    for kind, k in solid_lines(grid):
        if kind == 'r':
            top, bot = grid[:k], grid[k + 1:]
            if len(top) == len(bot) and len(top) > 0:
                return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(top, bot)]
        else:
            left = [row[:k] for row in grid]
            right = [row[k + 1:] for row in grid]
            if len(left[0]) == len(right[0]) and len(left[0]) > 0:
                return [[color if a and b else 0 for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
    raise ValueError('no separating solid line')


def recolor_scatter_to_bg(grid):
    """Each cell of the scattered (minority) color takes the background (majority) color, and the background becomes 0."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    return [[0 if v == bg else bg for v in row] for row in grid]

def shift_colors_down(grid):
    """Sorted distinct colors shift down one rank: the smallest becomes 0, each other color becomes the next smaller one."""
    s = sorted({v for row in grid for v in row})
    m = {s[0]: 0}
    for k in range(1, len(s)):
        m[s[k]] = s[k-1]
    return [[m[v] for v in row] for row in grid]

def remap_min_to_zero(grid):
    """The grid with its smallest nonzero color mapped to 0 and the other colors shifted one rank down."""
    s = sorted({v for row in grid for v in row} - {0})
    if not s:
        return [row[:] for row in grid]
    m = {s[0]: 0}
    for k in range(1, len(s)):
        m[s[k]] = s[k-1]
    return [[m[v] for v in row] for row in grid]


def demote_minority(grid, base=5):
    """Color base (default 5) becomes the grid's other color, and that other color becomes 0."""
    other = next(k for k in {v for row in grid for v in row} if k != base)
    return [[other if v == base else 0 for v in row] for row in grid]

def recolor_full_lines(grid, color=2):
    """Every row and every column that is one solid color throughout is recolored to the given color."""
    h, w = len(grid), len(grid[0])
    fullrows = {i for i, row in enumerate(grid) if len(set(row)) == 1}
    fullcols = {j for j in range(w) if len({row[j] for row in grid}) == 1}
    return [[color if (i in fullrows or j in fullcols) else v for j, v in enumerate(row)] for i, row in enumerate(grid)]

